B.btB=new A.D("Klas\xf6rler","Bir kay\u0131tta \u201cKlas\xf6re koy\u201d ile klas\xf6r ver (\xf6r. \u201cT\xfcrk\xfcler\u201d, \u201cDers\u201d). \xdcstteki klas\xf6r d\xfc\u011fmeleriyle sadece o klas\xf6r\xfc g\xf6r\xfcrs\xfcn.")
B.bsL=new A.D("Geli\u015ftiriciye g\xf6nder","Bir kay\u0131tta notalar \xe7ok yanl\u0131\u015f \xe7\u0131kt\u0131ysa men\xfcden \u201cGeli\u015ftiriciye g\xf6nder\u201d ile kayd\u0131 geli\u015ftiriciye yollayabilirsin; inceleyip uygulamay\u0131 d\xfczeltir. Bu, kayd\u0131n g\xf6nderildi\u011fi tek durumdur.")
